import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.DwAI3uWn.js";const u=JSON.parse('{"title":"Chainy mentor skills","description":"These six project-local AI advisory skills challenge proposals using evidence and offer bounded alternatives. They are capabilities, not actual appointed people, separate agen","frontmatter":{"title":"Chainy mentor skills","description":"These six project-local AI advisory skills challenge proposals using evidence and offer bounded alternatives. They are capabilities, not actual appointed people, separate agen","source":"docs/mentors.md","category":"Repository & agent guidance","sourceUpdated":"2026-10-05T06:23:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/mentors.md","filePath":"content/docs/mentors.md"}'),o={name:"content/docs/mentors.md"};function r(s,e,d,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-mentor-skills">Chainy mentor skills<a class="header-anchor" href="#chainy-mentor-skills" aria-label="Link to this section">​</a></h1><p>These six project-local AI advisory skills challenge proposals using evidence and offer bounded alternatives. They are capabilities, not actual appointed people, separate agents, or substitutes for an adviser. They complement the existing eight implementation skills.</p><table><thead><tr><th>Mentor</th><th>Invoke</th><th>Challenge it should make</th></tr></thead><tbody><tr><td>Scope and feasibility</td><td><code>$capstone-scope-mentor</code></td><td>Does this fit the available person-hours and defense deadline, and what gets displaced?</td></tr><tr><td>Technical delivery</td><td><code>$unity-delivery-mentor</code></td><td>Can this work on the actual Android device with the chosen Unity and SQLite setup?</td></tr><tr><td>Learning and age appropriateness</td><td><code>$learning-design-mentor</code></td><td>Does the mechanic teach a measurable concept at an appropriate level for ages 13–17?</td></tr><tr><td>Blockchain and AI accuracy</td><td><code>$simulation-accuracy-mentor</code></td><td>Is the simulation teaching a false model or claiming capabilities it does not implement?</td></tr><tr><td>Offline data and evaluation</td><td><code>$offline-evidence-mentor</code></td><td>Can the teacher reliably retrieve only the evidence needed, without a cloud dependency?</td></tr><tr><td>Defense readiness</td><td><code>$defense-readiness-mentor</code></td><td>Can the team demonstrate and substantiate each claimed rubric result?</td></tr></tbody></table><p>Read the actual instructions under <a href="/Chainy-Docs/folders/agents/skills.html">project skills</a>. Their context is the <a href="/Chainy-Docs/content/docs/project-baseline.html">current baseline</a>, not the older source reports.</p><h2 id="working-agreement">Working agreement<a class="header-anchor" href="#working-agreement" aria-label="Link to this section">​</a></h2><p>Use the relevant mentor when proposing a feature, selecting an uncertain technical approach, or checking a checkpoint. Do not require all six reviews for every small task. Advice should state a verdict, evidence, tradeoff, and one executable next step. A requirement is not erased merely because it is hard.</p><p>The immediate recommendation is <strong>reduce scale and validate first</strong>. Free construction, node synchronization, example-based classification and an agent puzzle are retained; expansive worlds, custom online services and extra reward systems should not consume the pre-final window. These limits are proposed until capacity and rubric are known.</p><h2 id="human-guidance-still-needed">Human guidance still needed<a class="header-anchor" href="#human-guidance-still-needed" aria-label="Link to this section">​</a></h2><ul><li>Capstone adviser/panel representative: confirms the rubric, scope approval and evidence required on November 21.</li><li>Experienced Unity Android developer: reviews the first device build, SQLite integration and performance spike.</li><li>Blockchain/AI subject reviewer: checks toy-model assumptions and educational wording.</li><li>Educator or instructional designer familiar with ages 13–17: reviews difficulty, language and assessment alignment.</li><li>Cryptita Plays site coordinator or teacher: confirms device access, delivery, scheduling and collection workflow.</li><li>School research supervisor or designated data custodian: approves the evaluation process and handling of participant records.</li></ul><p>These are roles to fill, not invented named mentors or claims that anyone has agreed to serve.</p></div>',1)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
